-- Final-schema DDL for PostgreSQL storage (ATASK_DB_URL=postgres://...).
-- Column names, types, and constraints mirror the SQLite schema after
-- migrations 0001..0025 exactly; only the engine-specific mechanics differ:
--   * INTEGER PRIMARY KEY rowid aliases (tasks.id is TEXT) become
--     BIGINT GENERATED BY DEFAULT AS IDENTITY, so explicit ids (sync from
--     SQLite) and allocated ones (RETURNING id) coexist;
--   * every column keeps SQLite's type, including INTEGER 0/1 for boolean
--     facts (required, reused, passed, detach, timed_out, manual,
--     sandboxed) — the Go code stores ints there on both engines;
--   * policy_json / members_json / options_json / run_json stay TEXT
--     (canonical JSON strings), never jsonb: a jsonb write would
--     normalize key order and break the stored-digest equality the
--     verification contract relies on.
-- The applied state of this script is recorded in schema_migrations as
-- version 9000000000 (sqlite migrations never reach it), so applying is
-- idempotent and a SQLite-migrated ledger never collides.

CREATE TABLE IF NOT EXISTS schema_migrations (
    version    BIGINT PRIMARY KEY,
    name       TEXT NOT NULL,
    applied_at BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS projects (
    id               TEXT PRIMARY KEY,
    name             TEXT NOT NULL,
    root_path        TEXT UNIQUE,                 -- NULL: project has no directory
    integration      TEXT NOT NULL DEFAULT 'none',
    plan_rev         BIGINT NOT NULL DEFAULT 0,
    target_branch    TEXT NOT NULL DEFAULT '',
    workspace_root   TEXT NOT NULL DEFAULT '',
    max_attempts     BIGINT NOT NULL DEFAULT 5,
    retry_cooldown_ms BIGINT NOT NULL DEFAULT 0,
    created_at       BIGINT NOT NULL,
    updated_at       BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS tasks (
    id                       TEXT PRIMARY KEY,
    project_id               TEXT NOT NULL REFERENCES projects(id),
    description              TEXT NOT NULL,
    outcome                  TEXT NOT NULL,
    constraints_json         TEXT NOT NULL DEFAULT '[]',
    policy_json              TEXT NOT NULL DEFAULT '',
    policy_digest            TEXT NOT NULL,
    current_attempt_seq      BIGINT NOT NULL DEFAULT 0,
    latest_submission_id     BIGINT,
    completed_at             BIGINT,
    completed_submission_id  BIGINT,
    created_at               BIGINT NOT NULL,
    updated_at               BIGINT NOT NULL,
    manual                   BIGINT NOT NULL DEFAULT 0,
    key                      TEXT,
    kind                     TEXT NOT NULL DEFAULT 'task',
    parent_id                TEXT REFERENCES tasks(id),
    cohort                   TEXT NOT NULL DEFAULT '',
    archived_at              BIGINT,
    failures                 BIGINT NOT NULL DEFAULT 0,
    next_eligible_at         BIGINT NOT NULL DEFAULT 0,
    contract_rev             BIGINT NOT NULL DEFAULT 1,
    archive_reason           TEXT NOT NULL DEFAULT '',
    last_failure_attempt_id  BIGINT NOT NULL DEFAULT 0,
    last_error               TEXT NOT NULL DEFAULT '',
    workspace_error          TEXT NOT NULL DEFAULT '',
    pins_json                TEXT NOT NULL DEFAULT '[]',
    creator                  TEXT NOT NULL DEFAULT '',
    created_cwd              TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS tasks_project_created ON tasks(project_id, created_at, id);
CREATE INDEX IF NOT EXISTS tasks_project_open ON tasks(project_id, created_at, id) WHERE completed_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS tasks_project_key ON tasks(project_id, key) WHERE key IS NOT NULL;
CREATE INDEX IF NOT EXISTS tasks_parent ON tasks(parent_id) WHERE parent_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS tasks_cohort ON tasks(project_id, cohort) WHERE cohort <> '';

CREATE TABLE IF NOT EXISTS acceptance_criteria (
    task_id     TEXT NOT NULL REFERENCES tasks(id),
    position    BIGINT NOT NULL,
    description TEXT NOT NULL,
    PRIMARY KEY (task_id, position)
);

CREATE TABLE IF NOT EXISTS task_dependencies (
    task_id     TEXT NOT NULL REFERENCES tasks(id),
    requires_id TEXT NOT NULL REFERENCES tasks(id),
    created_at  BIGINT NOT NULL,
    PRIMARY KEY (task_id, requires_id),
    CHECK (task_id <> requires_id)
);
CREATE INDEX IF NOT EXISTS task_dependencies_requires ON task_dependencies(requires_id, task_id);

CREATE TABLE IF NOT EXISTS execution_attempts (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id          TEXT NOT NULL REFERENCES tasks(id),
    seq              BIGINT NOT NULL,
    token_digest     TEXT NOT NULL UNIQUE,
    started_at       BIGINT NOT NULL,
    lease_expires_at BIGINT NOT NULL,
    ended_at         BIGINT,
    end_reason       TEXT,
    workspace_path   TEXT NOT NULL DEFAULT '',
    workspace_branch TEXT NOT NULL DEFAULT '',
    lease_ms         BIGINT NOT NULL DEFAULT 0,
    UNIQUE (task_id, seq)
);

CREATE TABLE IF NOT EXISTS task_log_entries (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id     TEXT NOT NULL REFERENCES tasks(id),
    attempt_id  BIGINT NOT NULL REFERENCES execution_attempts(id),
    done        TEXT NOT NULL DEFAULT '',
    next        TEXT NOT NULL DEFAULT '',
    learned     TEXT NOT NULL DEFAULT '',
    note        TEXT NOT NULL DEFAULT '',
    created_at  BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS task_log_entries_task ON task_log_entries(task_id, id);

CREATE TABLE IF NOT EXISTS submissions (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id      TEXT NOT NULL REFERENCES tasks(id),
    attempt_id   BIGINT NOT NULL REFERENCES execution_attempts(id),
    revision     TEXT NOT NULL DEFAULT '',
    cohort       TEXT NOT NULL DEFAULT '',
    submitted_at BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS submissions_task ON submissions(task_id, id);
CREATE INDEX IF NOT EXISTS submissions_attempt ON submissions(attempt_id, id);

CREATE TABLE IF NOT EXISTS verification_runs (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id             TEXT NOT NULL REFERENCES tasks(id),
    attempt_id          BIGINT REFERENCES execution_attempts(id),
    submission_id       BIGINT REFERENCES submissions(id),
    job_id              BIGINT,
    mode                TEXT NOT NULL DEFAULT 'complete',
    status              TEXT NOT NULL,
    revision            TEXT NOT NULL DEFAULT '',
    integrated_revision TEXT NOT NULL DEFAULT '',
    policy_json         TEXT NOT NULL DEFAULT '',
    policy_digest       TEXT NOT NULL,
    environment         TEXT NOT NULL DEFAULT '',
    created_at          BIGINT NOT NULL,
    started_at          BIGINT,
    finished_at         BIGINT,
    summary             TEXT NOT NULL DEFAULT '',
    heartbeat_at        BIGINT NOT NULL DEFAULT 0,
    heartbeat_every_ms BIGINT NOT NULL DEFAULT 0,
    owner_pid           BIGINT NOT NULL DEFAULT 0,
    owner_host          TEXT NOT NULL DEFAULT '',
    owner_start         TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS verification_runs_submission ON verification_runs(submission_id, id);
CREATE INDEX IF NOT EXISTS verification_runs_task ON verification_runs(task_id, id);
CREATE INDEX IF NOT EXISTS verification_runs_job ON verification_runs(job_id) WHERE job_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS verification_results (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    run_id         BIGINT NOT NULL REFERENCES verification_runs(id),
    check_id       TEXT NOT NULL,
    check_version  TEXT NOT NULL DEFAULT '',
    check_digest   TEXT NOT NULL,
    required       BIGINT NOT NULL,
    revision       TEXT NOT NULL DEFAULT '',
    policy_digest  TEXT NOT NULL,
    started_at     BIGINT NOT NULL,
    finished_at    BIGINT NOT NULL,
    exit_code      BIGINT NOT NULL,
    outcome        TEXT NOT NULL,
    reused         BIGINT NOT NULL DEFAULT 0,
    reused_from    BIGINT,
    message        TEXT NOT NULL DEFAULT '',
    stdout         TEXT NOT NULL DEFAULT '',
    stderr         TEXT NOT NULL DEFAULT '',
    log            TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS verification_results_run ON verification_results(run_id, id);
CREATE INDEX IF NOT EXISTS verification_results_reuse ON verification_results(check_digest, revision, outcome) WHERE reused = 0;

CREATE TABLE IF NOT EXISTS run_results (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id      TEXT NOT NULL,
    attempt_id   BIGINT,
    run_id       BIGINT NOT NULL REFERENCES verification_runs(id),
    evidence_id  BIGINT NOT NULL REFERENCES verification_results(id),
    check_type   TEXT NOT NULL,
    preset       TEXT NOT NULL,
    subject      TEXT NOT NULL,
    options_json TEXT NOT NULL DEFAULT '{}',
    started_at   BIGINT NOT NULL,
    elapsed_ms   BIGINT NOT NULL,
    budget_ms    BIGINT NOT NULL,
    timed_out    BIGINT NOT NULL,
    return_code  BIGINT,
    passed       BIGINT NOT NULL,
    output       TEXT NOT NULL DEFAULT '',
    sandboxed   BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS run_results_task ON run_results(task_id, id);
CREATE INDEX IF NOT EXISTS run_results_run ON run_results(run_id, id);

CREATE TABLE IF NOT EXISTS actions (
    task_id      TEXT NOT NULL,
    position     BIGINT NOT NULL,
    preset       TEXT NOT NULL,
    subject      TEXT NOT NULL,
    options_json TEXT NOT NULL DEFAULT '{}',
    detach       BIGINT NOT NULL,
    status       TEXT NOT NULL DEFAULT 'pending',
    attempts     BIGINT NOT NULL DEFAULT 0,
    run_json     TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (task_id, position)
);

CREATE TABLE IF NOT EXISTS check_history (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id    TEXT NOT NULL REFERENCES tasks(id),
    changed_at BIGINT NOT NULL,
    field      TEXT NOT NULL,
    old_spec   TEXT NOT NULL,
    new_spec   TEXT NOT NULL,
    actor      TEXT NOT NULL,
    cwd        TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS check_history_task ON check_history(task_id, id);

CREATE TABLE IF NOT EXISTS plan_changes (
    project_id      TEXT NOT NULL REFERENCES projects(id),
    idempotency_key TEXT NOT NULL,
    plan_rev        BIGINT NOT NULL,
    result_json     TEXT NOT NULL,
    applied_at      BIGINT NOT NULL,
    request_digest  TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (project_id, idempotency_key)
);

CREATE TABLE IF NOT EXISTS verification_jobs (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id       TEXT NOT NULL REFERENCES projects(id),
    cohort           TEXT NOT NULL,
    status           TEXT NOT NULL,
    members_json     TEXT NOT NULL,
    owner_digest     TEXT NOT NULL DEFAULT '',
    lease_expires_at BIGINT NOT NULL DEFAULT 0,
    candidate        TEXT NOT NULL DEFAULT '',
    created_at       BIGINT NOT NULL,
    finished_at      BIGINT,
    summary          TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS verification_jobs_cohort ON verification_jobs(project_id, cohort, id);

CREATE TABLE IF NOT EXISTS integration_records (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id      TEXT NOT NULL REFERENCES projects(id),
    task_id         TEXT REFERENCES tasks(id),
    job_id          BIGINT,
    target_branch   TEXT NOT NULL,
    base_revision   TEXT NOT NULL,
    source_revision TEXT NOT NULL,
    result_revision TEXT NOT NULL,
    created_at      BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS integration_intents (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id         TEXT NOT NULL REFERENCES projects(id),
    task_id            TEXT NOT NULL REFERENCES tasks(id),
    attempt_id         BIGINT REFERENCES execution_attempts(id),
    job_id             BIGINT,
    run_id             BIGINT NOT NULL,
    submission_id      BIGINT NOT NULL,
    owner_digest       TEXT NOT NULL,
    contract_rev       BIGINT NOT NULL,
    regression_digest  TEXT NOT NULL,
    target_branch      TEXT NOT NULL,
    base_revision      TEXT NOT NULL,
    source_revision    TEXT NOT NULL,
    candidate_revision TEXT NOT NULL,
    status             TEXT NOT NULL,
    created_at         BIGINT NOT NULL,
    finished_at        BIGINT,
    summary            TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS integration_intents_task ON integration_intents(task_id, id);
CREATE INDEX IF NOT EXISTS integration_intents_open ON integration_intents(project_id, id) WHERE status = 'intended';

CREATE TABLE IF NOT EXISTS task_projects (
    task_id    TEXT NOT NULL REFERENCES tasks(id),
    project_id TEXT NOT NULL REFERENCES projects(id),
    position   BIGINT NOT NULL,
    PRIMARY KEY (task_id, project_id),
    UNIQUE (task_id, position)
);
CREATE INDEX IF NOT EXISTS task_projects_by_project ON task_projects (project_id, task_id);
